-- 读接口归属按「菜单 path + 接口 path」恢复:api_id 为自增列,跨库会漂移,不能硬编码。
DELETE ma FROM `sys_menu_api` ma JOIN `sys_menu` m ON m.`id`=ma.`menu_id` JOIN `sys_api` a ON a.`id`=ma.`api_id` WHERE m.`path` IN ('/media/overview','/media/monitoring','/media/ingress','/media/nodes','/media/scheduling') AND a.`path` LIKE '/api/gb28181/zlm/%';
UPDATE `sys_menu` SET `parent_id`=140355,`path`='/gb28181/realtime-log',`sort`=6,`updated_at`=NOW() WHERE `path`='/system/realtime-log' AND `deleted_at` IS NULL;
